begin;
do $$
declare u1 uuid:=gen_random_uuid();u2 uuid:=gen_random_uuid();u3 uuid:=gen_random_uuid(); outsider uuid:=gen_random_uuid();
 p1 uuid:=gen_random_uuid();p2 uuid:=gen_random_uuid();p3 uuid:=gen_random_uuid();gid uuid:=gen_random_uuid();game uuid:=gen_random_uuid();
 sid1 uuid;sid2 uuid;goal1 uuid:=gen_random_uuid();goal2 uuid:=gen_random_uuid();events jsonb;requests integer;
begin
 insert into auth.users(id) values(u1),(u2),(u3),(outsider);
 insert into public.groups(id,name) values(gid,'Pitch VAR transactional test');
 insert into public.players(id,group_id,user_id,name,nick,is_organizer) values(p1,gid,u1,'VAR Test Organizer','VAR-Org',true),(p2,gid,u2,'VAR Test Camera','VAR-Cam',false),(p3,gid,u3,'VAR Test Scorer','VAR-Scorer',false);
 insert into public.player_group_memberships(player_id,group_id,role) values(p1,gid,'organizer'),(p2,gid,'member'),(p3,gid,'member') on conflict(player_id,group_id) do update set role=excluded.role;
 insert into public.games(id,group_id,scheduled_at,live_matchday) values(game,gid,now(),'{"matches":[{"id":"fixture-1","n":1,"events":[]}]}'::jsonb);
 insert into public.attendances(game_id,player_id,status) values(game,p1,'confirmed'),(game,p2,'confirmed'),(game,p3,'confirmed');
 perform set_config('request.jwt.claim.sub',u1::text,true);
 perform public.pitch_var('toggle',jsonb_build_object('gameId',game,'enabled',true));
 sid1:=(public.pitch_var('join',jsonb_build_object('gameId',game,'matchId','fixture-1','deviceId',gen_random_uuid(),'startServerMs',extract(epoch from now()-interval '8 seconds')*1000,'uncertaintyMs',100))->>'sessionId')::uuid;
 perform set_config('request.jwt.claim.sub',u2::text,true);
 sid2:=(public.pitch_var('join',jsonb_build_object('gameId',game,'matchId','fixture-1','deviceId',gen_random_uuid(),'startServerMs',extract(epoch from now()-interval '8 seconds')*1000,'uncertaintyMs',100))->>'sessionId')::uuid;
 events:=jsonb_build_array(jsonb_build_object('eventId',goal1,'scorerPlayerId',p3,'occurredAt',now()-interval '1 second','scorerId',3));
 update public.games set live_matchday=jsonb_build_object('matches',jsonb_build_array(jsonb_build_object('id','fixture-1','n',1,'events',events))) where id=game;
 select count(*) into requests from public.var_requests where goal_id=goal1;
 if requests<>2 then raise exception 'Expected two cameras, got %',requests;end if;
 update public.games set live_matchday=live_matchday where id=game;
 if (select count(*) from public.var_requests where goal_id=goal1)<>2 then raise exception 'Duplicate goal dispatch';end if;
 perform set_config('request.jwt.claim.sub',u1::text,true);
 perform public.pitch_var('stop',jsonb_build_object('sessionId',sid1));
 events:=events||jsonb_build_array(jsonb_build_object('eventId',goal2,'scorerPlayerId',p3,'occurredAt',now(),'scorerId',3));
 update public.games set live_matchday=jsonb_build_object('matches',jsonb_build_array(jsonb_build_object('id','fixture-1','n',1,'events',events))) where id=game;
 if (select count(*) from public.var_requests where goal_id=goal2)<>1 then raise exception 'Stopped camera got new goal';end if;
 perform set_config('request.jwt.claim.sub',outsider::text,true);
 begin perform public.pitch_var('join',jsonb_build_object('gameId',game,'matchId','fixture-1'));raise exception 'Outsider could join';exception when insufficient_privilege then null;end;
 begin perform public.pitch_var('toggle',jsonb_build_object('gameId',game,'enabled',false));raise exception 'Outsider could toggle';exception when insufficient_privilege then null;end;
 begin perform public.pitch_var('poll',jsonb_build_object('sessionId',sid2));raise exception 'Outsider could read requests';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',u1::text,true);
 update public.games set live_matchday=null where id=game;
 if exists(select 1 from public.var_goals where game_id=game and expires_at>now()+interval '3 hours 1 second') then raise exception 'Retention longer than 3h after finish';end if;
 if exists(select 1 from public.var_sessions where game_id=game and active) then raise exception 'Finished game kept cameras active';end if;
end;
$$;
rollback;
